// promptSyncDisabled resolves strategy_options.sync_prompts for the repository
// Open serves (same context-based resolution as LoadCheckpointsConfig). Unlike
// backend selection it is not fail-soft: sync_prompts=false is a privacy
// opt-out, so settings that cannot be read fail the open rather than silently
// writing prompts the user asked to keep local — the same fail-closed stance
// the redaction scanners take.
func promptSyncDisabled(ctx context.Context) (bool, error) {
	s, err := settings.Load(ctx)
	if err != nil {
		return false, fmt.Errorf("resolve %s setting: %w", settings.SyncPromptsOptionKey, err)
	}
	return s.IsPromptSyncDisabled(), nil
}

